    fn beacon_color() -> color {
        if (beacon_state == 0) {
            return #3a3a3a;
        } else if (beacon_state == 1) {
            return #ffb000;
        } else {
            return #22c55e;
        }
    }

    on key_down(key: Key) {
        if (key == Key.Space) {
            if (beacon_state == 0) {
                beacon_state = 1;
                elapsed_time = 0.0;
            } else if (beacon_state == 2) {
                beacon_state = 0;
            }
        }
    }
